#!/usr/bin/env python
"""Train SynthER (Lu et al., 2023): IQL on transitions generated by a diffusion model of the dataset.

    python baselines/train.py -c robustrllib/configs/experiment/synther_hopper.yaml --seed 0

1. fit the diffusion model (settings under ``hparams.diffusion``) to the run's dataset,
   packed as [state, action, reward, next state, terminal];
2. sample ``num_samples`` transitions; terminals are thresholded at 0.5, actions are clipped
   to the range of the real actions, and the task's ``binary_obs_dims`` are rounded to 0/1;
3. train IQL on the samples only, with observations normalised by the real data's mean and
   standard deviation (+1e-3), using the IQL training loop of baselines/iql/train.py.

The samples are written to ``<run>/samples.npz``; ``hparams.samples`` names an existing file
to skip steps 1-2.
"""
from __future__ import annotations

from pathlib import Path

import numpy as np
import torch

from baselines.iql.agent import IQLAgent
from baselines.iql.train import agent_kwargs, fit
from baselines.offline.common import make_env, parse_config, setup
from baselines.offline.data import Dataset, Episode, load_dataset
from baselines.synther.diffusion import train_diffusion


def generate(real: Dataset, path: Path, binary_dims, seed, device, hp) -> None:
    d, a = real.state_dim, real.action_dim
    inputs = np.concatenate([real.states, real.actions, real.rewards, real.next_states, real.dones], 1)
    model = train_diffusion(inputs, skip=[inputs.shape[1] - 1], seed=seed, device=device, **(hp.get("diffusion") or {}))
    total, chunk = int(hp["num_samples"]), int(hp["sample_batch_size"])
    steps = int((hp.get("diffusion") or {}).get("sample_steps", 128))
    parts = []
    for start in range(0, total, chunk):
        parts.append(model.sample(min(chunk, total - start), steps).cpu().numpy())
        print(f"[samples] {start + len(parts[-1])}/{total}", flush=True)
    x = np.concatenate(parts).astype(np.float32)
    obs, act, rew, nxt, done = x[:, :d], x[:, d:d + a], x[:, d + a], x[:, d + a + 1:2 * d + a + 1], x[:, -1]
    act = np.clip(act, real.actions.min(0), real.actions.max(0))
    for dim in binary_dims or []:
        obs[:, dim], nxt[:, dim] = obs[:, dim] >= 0.5, nxt[:, dim] >= 0.5
    np.savez_compressed(path, observations=obs, actions=act, rewards=rew, next_observations=nxt,
                        terminals=(done > 0.5).astype(np.float32))


def main() -> None:
    cfg = parse_config(__doc__)
    seed, device, out = setup(cfg)
    hp = cfg["algorithm"]["hparams"]
    real = load_dataset(cfg)
    path = Path(hp["samples"]) if hp.get("samples") else out / "samples.npz"
    if not path.exists():
        generate(real, path, cfg["task"].get("binary_obs_dims"), seed, device, hp)
    with np.load(path) as z:
        samples = Episode(z["observations"], z["actions"], z["rewards"].reshape(-1),
                          z["next_observations"], z["terminals"].reshape(-1))
    data = Dataset([samples], seed=seed)
    print(f"[data] {len(data)} generated transitions from {path}", flush=True)
    env = make_env(cfg["task"], seed)
    agent = IQLAgent(**agent_kwargs(cfg, data, env, seed, device))
    agent.set_normalization(real.states.mean(0), real.states.std(0) + 1e-3)
    del real
    torch.cuda.empty_cache()
    fit(agent, data, cfg, out, env)


if __name__ == "__main__":
    main()
